module ldpcdec_main_tbl (
    // System signals
    input clk,                      // system clock
    input rst_n,                    // system asynchronous reset, active low

    // Data interface
    input [11:0] addr,              // read address, [7:0]:cnt, [9:8]:rate, [11:10]:codeword length
    output reg [4:0] q_raddr,       // read address for LQ
    output reg q_byp,               // data bypass for LQ
    output reg [8:0] q_sh,          // shift number for LQ
    output reg [1:0] q_vld,         // valid for LQ
    output reg [6:0] r_raddr,       // read address for Lr
    output reg r_vld,               // valid for Lr
    output reg [4:0] t_raddr,       // read address for Lq
    output reg t_byp,               // data bypass for Lq
    output reg t_vld,               // valid for Lq
    output reg [6:0] r_waddr,       // write address for Lr
    output reg [8:0] q_hd_sh,       // shift number for LQ hard decision bits
    output reg [4:0] q_hd_waddr,    // write address for LQ hard decision bits
    output reg q_hd_vld             // valid for LQ hard decision bits
);

// Local signals
reg [4:0] q_raddr_w;
reg q_byp_w;
reg [8:0] q_sh_w;
reg [1:0] q_vld_w;
reg [6:0] r_raddr_w;
reg r_vld_w;
reg [4:0] t_raddr_w;
reg t_byp_w;
reg t_vld_w;
reg [6:0] r_waddr_w;
reg [8:0] q_hd_sh_w;
reg [4:0] q_hd_waddr_w;
reg q_hd_vld_w;


// Tables
