// Output data
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        q_raddr <= 5'h0;
        q_byp <= 1'b0;
        q_vld <= 2'h0;
        r_raddr <= 7'h0;
        r_vld <= 1'b0;
        t_raddr <= 5'h0;
        t_byp <= 1'b0;
        t_vld <= 1'b0;
        r_waddr <= 7'h0;
        q_hd_waddr <= 5'h0;
        q_hd_vld <= 1'b0;
    end
    else begin
        q_raddr <= q_raddr_w;
        q_byp <= q_byp_w;
        q_vld <= q_vld_w;
        r_raddr <= r_raddr_w;
        r_vld <= r_vld_w;
        t_raddr <= t_raddr_w;
        t_byp <= t_byp_w;
        t_vld <= t_vld_w;
        r_waddr <= r_waddr_w;
        q_hd_waddr <= q_hd_waddr_w;
        q_hd_vld <= q_hd_vld_w;
    end
end

always @(posedge clk) begin
    q_sh <= q_sh_w;
    q_hd_sh <= q_hd_sh_w;
end


endmodule
